package org.sleepwell.app;

import org.junit.Test;
import static org.junit.Assert.*;

public final class SoundAnalysisStatusTest {
 @Test public void explicitOffCannotBeEscalatedByResume(){SoundAnalysisStatus off=SoundAnalysisStatus.initial(false);assertEquals("off",off.state);assertThrows(IllegalArgumentException.class,()->SoundAnalysisStatus.initial(true).follows(off));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(false,"complete",1,""));}
 @Test public void actualInferencesDoNotRequireAnyClassifiedEvent(){SoundAnalysisStatus pending=SoundAnalysisStatus.initial(true),active=new SoundAnalysisStatus(true,"active",2,"");active.follows(pending);new SoundAnalysisStatus(true,"complete",2,"").follows(active);assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"complete",0,""));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"active",1,"").follows(active));}
 @Test public void pendingTooShortAndPartialErrorsRemainDistinct(){new SoundAnalysisStatus(true,"insufficient",0,"").follows(SoundAnalysisStatus.initial(true));SoundAnalysisStatus failed=new SoundAnalysisStatus(true,"error",3,"queue");failed.follows(new SoundAnalysisStatus(true,"active",3,""));assertSame(failed,failed.interrupted());assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"active",4,"").follows(failed));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"error",0,"private-path"));}
 @Test public void crashRecoveryKeepsActualDurableCountsAndImmutableConsent(){SoundAnalysisStatus pending=SoundAnalysisStatus.initial(true).interrupted(),active=new SoundAnalysisStatus(true,"active",7,"").interrupted();assertEquals("interrupted",pending.state);assertEquals(0,pending.frames);assertEquals(7,active.frames);assertEquals("interrupted",active.issue);assertFalse(SoundAnalysisStatus.initial(false).interrupted().requested);}
 @Test public void boundsAndStateCompatibilityRejectInventedEvidence(){for(long frames:new long[]{-1,SoundAnalysisStatus.MAX_FRAMES+1})assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"active",frames,""));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"pending",1,""));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"insufficient",1,""));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"active",1,"model"));assertThrows(IllegalArgumentException.class,()->new SoundAnalysisStatus(true,"active",1,"").follows(new SoundAnalysisStatus(true,"complete",1,"")));}
}
